class OFDPageGraphics2DTest {

    @Test
    void testTransformMethod() throws Exception {
        ElemCup.ENABLE_DEBUG_PRINT = true;
        final Path dst = Paths.get("target/testTransformMethod.ofd");
        try (OFDGraphicsDocument doc = new OFDGraphicsDocument(dst)) {
            OFDPageGraphics2D g = doc.newPage(500, 500);

            // Initial transformation is identity
            AffineTransform initial = new AffineTransform();
            assertEquals(initial, g.getTransform());

            // Apply rotation
            AffineTransform rotate = new AffineTransform();
            rotate.rotate(45 * Math.PI / 180d);
            g.transform(rotate);
            AffineTransform expectedAfterRotate = new AffineTransform(rotate);
            assertEquals(expectedAfterRotate, g.getTransform());

            // Apply scale
            AffineTransform scale = new AffineTransform();
            scale.scale(0.83, 0.83);
            g.transform(scale);
            AffineTransform expectedAfterScale = new AffineTransform(expectedAfterRotate);
            expectedAfterScale.concatenate(scale);
            assertEquals(expectedAfterScale, g.getTransform());

            // Apply shear
            AffineTransform shear = new AffineTransform();
            shear.shear(-0.58, 0.83);
            g.transform(shear);
            AffineTransform expectedAfterShear = new AffineTransform(expectedAfterScale);
            expectedAfterShear.concatenate(shear);
            assertEquals(expectedAfterShear, g.getTransform());

            // Apply translation
            AffineTransform translate = new AffineTransform();
            translate.translate(127.45, 127.45);
            g.transform(translate);
            AffineTransform expectedFinal = new AffineTransform(expectedAfterShear);
            expectedFinal.concatenate(translate);

            // Verify final transformation
            AffineTransform finalTransform = g.getTransform();
            assertEquals(expectedFinal, finalTransform);

            // Draw something to visualize the transformations
            g.setColor(Color.RED);
            g.fillRect(0, 0, 100, 100);
        }
        System.out.println(">> " + dst.toAbsolutePath());
    }

}

