                .setStyle("height", "300");
        segmentSequence.add(new Segment(div3, false));

        // 4. 创建一个可拆分的段落
        Div div4 = new Div()
                .setFloat(AFloat.LEFT)
                .setClear(Clear.BOTH)
                .setStyle("width", "400")
                .setStyle("height", "200");
        segmentSequence.add(new Segment(div4, true));

