        // Calculate remainWidth by subtracting the added div's width from segment's width
        double addedWidth = 50;
        double expectedRemainWidth = 138 - addedWidth;
        // Since we can't access remainWidth directly, we verify by checking if another div of width 50 can be added
        Div checkDiv = Div.placeholder(50, 100, AFloat.left);
        boolean canAdd = segment.tryAdd(checkDiv);
        Assertions.assertTrue(canAdd);
        // Reset for next check
        segment = new Segment(138d);
        segment.tryAdd(div1);
        // Verify height via getHeight()
        Assertions.assertEquals(100, segment.getHeight());

        // Test case 2: Try adding when segment is full
        segment = new Segment(138d);
        Div div2 = Div.placeholder(138, 50, AFloat.left);
        boolean added2 = segment.tryAdd(div2);
        Assertions.assertTrue(added2);
        // Try adding another div
        Div div3 = Div.placeholder(10, 30, AFloat.left);
        boolean added3 = segment.tryAdd(div3);
        Assertions.assertFalse(added3);

        // Test case 3: Reject due to floating element conflict when clear is set
        segment = new Segment(138d);
        Div div4 = Div.placeholder(60, 80, AFloat.left);
        boolean added4 = segment.tryAdd(div4);
        Assertions.assertTrue(added4);
        Div div5 = Div.placeholder(70, 90, AFloat.left).setClear(Clear.left);
        boolean added5 = segment.tryAdd(div5);
        Assertions.assertFalse(added5);

        // Test case 4: Handle clear properties
        segment = new Segment(138d);
        Div div6 = Div.placeholder(60, 80, AFloat.left);
        boolean added6 = segment.tryAdd(div6);
        Assertions.assertTrue(added6);
        Div div7 = Div.placeholder(70, 90, AFloat.left).setClear(Clear.left);
        boolean added7 = segment.tryAdd(div7);
        Assertions.assertFalse(added7);

        // Test case 5: Check height update
        segment = new Segment(138d);
        Div div8 = Div.placeholder(50, 100, null);
        boolean added8 = segment.tryAdd(div8);
        Assertions.assertTrue(added8);
        Assertions.assertEquals(100, segment.getHeight());
        Div div9 = Div.placeholder(50, 120, null);
        boolean added9 = segment.tryAdd(div9);
        Assertions.assertTrue(added9);
        // Height should be the maximum of 100 and 120
