import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.Files;
import java.io.IOException;

class SignCleanerTest {

    private Path testInput;
    private Path outputDir;
    private Path testOutput;

    @BeforeEach
    void setUp() throws IOException {
        // Set up test resources and output directory
        testInput = Paths.get("src/test/resources/OFD/v4signed OFD document.ofd");
        outputDir = Paths.get("target/test-output");
        String fileName = testInput.getFileName().toString();
        testOutput = outputDir.resolve(fileName);

        // Create output directory if not exists
        Files.createDirectories(outputDir);

        // Ensure output file does not exist before test
        if (Files.exists(testOutput)) {
            Files.delete(testOutput);
        }

        // Verify input file exists
        assertTrue(Files.exists(testInput), "Input file should exist");
    }

    @Test
    void testCleanSignatures() throws IOException, org.dom4j.DocumentException {
        // Create OFDReader instance
        OFDReader reader = new OFDReader(testInput);

        // Create SignCleaner instance
        SignCleaner cleaner = new SignCleaner(reader, outputDir);

        // Execute cleaning process
        cleaner.clean();

        // Verify output file exists
        assertTrue(Files.exists(testOutput), "Output file should be created");

        // Verify no signature-related files or directories exist
        Path signsDir = testOutput.resolve("Signs");
        assertFalse(Files.exists(signsDir), "Signs directory should be removed");

        Path signaturesXml = testOutput.resolve("Signatures.xml");
        assertFalse(Files.exists(signaturesXml), "Signatures.xml file should be removed");
    }

    @AfterEach
    void tearDown() throws IOException {
        // Clean up test output directory
        if (Files.exists(testOutput)) {
            Files.delete(testOutput);
        }
        if (Files.exists(outputDir)) {
            Files.delete(outputDir);
        }
    }
}

